function classifyMessage(message) {
  const text = String(message || '').toLowerCase();
  const linkMatches = text.match(/https?:\/\/|www\./g);
  const linkCount = linkMatches ? linkMatches.length : 0;
  const spamWord = ['casino', 'crypto', 'viagra'].some((word) => text.includes(word));
  const spam = spamWord || text.includes('seo backlinks') || text.includes('backlink') || linkCount >= 3;
  if (spam) return 'spam';
  if (['price', 'quote', 'order'].some((word) => text.includes(word))) return 'sales';
  if (['error', 'broken', 'refund', 'help'].some((word) => text.includes(word))) return 'support';
  return 'general';
}

const raw = $('Receive Inquiry').first().json;
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const name = String(body.name || '').trim();
const email = String(body.email || '').trim();
const company = String(body.company || '').trim();
const message = String(body.message || '').trim();
return [{
  json: {
    name: name,
    email: email,
    company: company,
    message: message,
    category: classifyMessage(message),
    received_at: new Date().toISOString(),
  },
}];

const item = $('Classify Inquiry').first().json;
return [{
  json: {
    category: item.category,
    row: {
      name: item.name,
      email: item.email,
      company: item.company,
      message: item.message,
      category: item.category,
      received_at: item.received_at,
    },
  },
}];
